    // Per-adapter credential help
    'fleet_token_help' => 'Vygenerujte ho vo vašej inštancii Fleet v časti My Account -> Get API token. Vyžaduje rolu admin alebo observer s prístupom na čítanie k hostom (a k tímom, ak používate mapovanie skupín na spoločnosti).',
    'kandji_token_help' => 'Vygenerujte ho vo vašom nájomníkovi Iru (Kandji) v časti Settings -> Access -> API Token. Vyžaduje oprávnenie na čítanie zoznamu zariadení Device list (a zoznamu Blueprint, ak používate mapovanie skupín na spoločnosti).',
    'kandji_base_url_help' => 'URL adresa API vášho Iru (Kandji) je uvedená na stránke Access v administrátorskej konzole Iru (Kandji) v sekcii API Token. Nie je to tá istá URL adresa, ktorú používate na prihlásenie do administrátorskej konzoly. Uložte URL adresu, ktorá končí na <code>.api.kandji.io</code>, nie URL adresu nástenky.',
    'jamf_client_id_help' => 'V Jamf Pro v časti Settings -> System -> API Roles and Clients vytvorte API rolu s oprávnením Read on Computers (a Read on Sites, ak používate mapovanie skupín na spoločnosti, a Read on Mobile Devices, ak nižšie zapnete prepínač mobilných zariadení) a potom API klienta, ktorý túto rolu používa. Client ID skopírujte zo stránky s detailom API klienta. Životnosť tokenu je v Jamf možné nastaviť pre každého API klienta. Snipe-IT token počas celej synchronizácie ukladá do vyrovnávacej pamäte a pred jeho vypršaním ho automaticky vymení, takže funguje akákoľvek rozumná životnosť.',
    'jamf_client_secret_help' => 'Používa sa spolu s vyššie uvedeným Client ID. Jamf Pro zobrazí tajný kľúč iba raz, pri vytvorení API klienta.',
    'jamf_label_include_mobile_devices' => 'Zahrnúť mobilné zariadenia',
    'jamf_include_mobile_devices_help' => 'Ak je zapnuté, Snipe-IT okrem počítačov stiahne z Jamf Pro aj zariadenia iOS / iPadOS / tvOS. Aby to fungovalo, API rola, ktorú ste vytvorili vyššie, musí navyše udeľovať oprávnenie Read on Mobile Devices.',
    'jamf_group_filter_label' => 'Filter skupín',
    'jamf_group_filter_help' => 'Čiarkou oddelené názvy (alebo ID) skupín Smart alebo Static Computer Group v Jamf Pro, na ktoré sa má synchronizácia obmedziť. Synchronizujú sa iba zariadenia, ktoré patria do niektorej z týchto skupín, všetko ostatné sa preskočí. Ak pole necháte prázdne, synchronizujú sa všetky zariadenia, ktoré API klient vidí. Ak vyššie zapnete prepínač mobilných zariadení, rovnaké názvy sa vyhľadajú aj medzi skupinami Mobile Device Groups, takže skupina s názvom "Law School", ktorá existuje v oboch menných priestoroch, filtruje obe flotily. Aby to fungovalo, API rola, ktorú ste vytvorili vyššie, musí mať oprávnenie Read on Computer Groups (a Read on Mobile Device Groups, ak zapnete prepínač mobilných zariadení). Príklad: "Law School, Faculty Loaners".',
    'jamf_extra_ram_gb' => 'Jamf – RAM (GB)',
    'jamf_extra_storage_gb' => 'Jamf – úložisko (GB)',
    'jamf_extra_mobile_device_type' => 'Typ mobilného zariadenia Jamf',
    'jamf_extra_mobile_managed' => 'Jamf mobilné – spravované',
    'jamf_extra_mobile_storage_gb' => 'Jamf – úložisko mobilného zariadenia (GB)',
    'jamf_extra_mobile_supervised' => 'Jamf mobilné – pod dohľadom',
    'jamf_school_network_id_help' => 'Network ID nájdete v administrátorskej konzole Jamf School v časti Organization -> Settings -> API.',
    'jamf_school_api_key_help' => 'Vygenerujte ho v Jamf School v časti Organization -> Settings -> API. Vyžaduje prístup na čítanie k Devices (a k Locations, ak používate mapovanie skupín na spoločnosti).',
    'jumpcloud_token_help' => 'Skopírujte ho zo stránky profilu administrátora JumpCloud (ponuka vpravo hore -> My API Key). API kľúče dedia oprávnenia administrátora, preto použite účet s prístupom na čítanie k Systems.',
    'mosyle_access_token_help' => 'Vygenerujte ho v administrátorskej konzole Mosyle Manager v časti Account -> API. Vyžaduje prístup na čítanie k Devices (a prístup na zápis, ak plánujete odosielať označenia majetku späť do Mosyle).',
    'mosyle_email_help' => 'E-mailová adresa administrátorského účtu Mosyle používaného na prihlásenie. Spolu s prístupovým tokenom a heslom slúži na získanie 24-hodinového JWT.',
    'mosyle_password_help' => 'Heslo pre vyššie uvedený administrátorský účet Mosyle. Odporúčame vytvoriť samostatný servisný účet s minimálnymi oprávneniami potrebnými na synchronizáciu namiesto opätovného použitia prihlasovacích údajov skutočného administrátora.',
    'mosyle_business_access_token_help' => 'Vygenerujte ho v administrátorskej konzole Mosyle Business v časti Organization -> API Integration. Vyžaduje prístup na čítanie k Devices (a prístup na zápis, ak plánujete odosielať označenia majetku alebo poznámky späť do Mosyle).',
    'mosyle_business_email_help' => 'E-mailová adresa administrátorského účtu Mosyle Business používaného na prihlásenie. Spolu s prístupovým tokenom a heslom slúži na získanie 24-hodinového JWT.',
    'mosyle_business_password_help' => 'Heslo pre vyššie uvedený administrátorský účet Mosyle Business. Odporúčame vytvoriť samostatný servisný účet s minimálnymi oprávneniami potrebnými na synchronizáciu namiesto opätovného použitia prihlasovacích údajov skutočného administrátora. Heslo je uložené šifrovane, ale z princípu je ho možné dešifrovať (pri každom prihlásení ho musíme poslať do Mosyle).',
