    // Custom HTTP adapter
    'custom_auth_method_help' => 'Spôsob, akým sa adaptér overuje voči vášmu API. <code>Bearer</code> posiela Bearer token v hlavičke <code>Authorization</code>. <code>Basic</code> posiela používateľské meno + heslo. <code>API Key</code> posiela hodnotu vo vlastnej hlavičke. <code>None</code> neposiela žiadne overovacie hlavičky.',
    'custom_bearer_token_help' => 'Používa sa, keď je spôsob overenia nastavený na <code>Bearer Token</code>. Hodnota sa posiela v hlavičke <code>Authorization: Bearer &lt;token&gt;</code>.',
    'custom_basic_username_help' => 'Používa sa, keď je spôsob overenia nastavený na <code>Basic Auth</code>.',
    'custom_basic_password_help' => 'Používa sa, keď je spôsob overenia nastavený na <code>Basic Auth</code>.',
    'custom_api_key_header_help' => 'Názov hlavičky, ktorú vaše API očakáva, napr. <code>X-API-Key</code> alebo <code>X-Auth-Token</code>. Používa sa, keď je spôsob overenia nastavený na <code>API Key Header</code>.',
    'custom_api_key_value_help' => 'Hodnota odosielaná vo vyššie nakonfigurovanej hlavičke.',
    'custom_pull_path_help' => 'Cesta pripojená k základnej URL adrese pri sťahovaní, napr. <code>/api/v1/devices</code>. Ak chcete volať priamo základnú URL adresu, nechajte prázdne.',
    'custom_records_path_help' => 'Cesta s bodkami v odpovedi JSON, kde sa nachádza pole záznamov, napr. <code>data.devices</code> alebo <code>results</code>. Ak je odpoveď už v koreni pole, nechajte prázdne.',
    'custom_source_id_path_help' => 'Povinné. Cesta s bodkami v rámci jedného záznamu, ktorá ukazuje na stabilný jedinečný identifikátor záznamu u poskytovateľa, napr. <code>id</code>, <code>uuid</code> alebo <code>serial_number</code>. Snipe-IT podľa tejto hodnoty páruje záznamy medzi jednotlivými synchronizáciami, takže ďalšie sťahovania aktualizujú ten istý majetok namiesto vytvárania duplikátov.',
    'custom_pagination_style_help' => 'Spôsob, akým adaptér prechádza za prvú stránku výsledkov poskytovateľa. <code>None</code> pošle jednu požiadavku a skončí. <code>Offset + Limit</code> opakovane volá ten istý koncový bod s parametrami <code>?limit=X&offset=Y</code>. <code>Page Number + Limit</code> opakovane volá s <code>?limit=X&page=N</code> (Snipe-IT API, API v štýle Laravel). <code>Next URL</code> nasleduje absolútnu URL adresu vrátenú v každej odpovedi.',
    'custom_pagination_page_size_help' => 'Počet záznamov požadovaných na stránku. Predvolene <code>500</code>.',
    'custom_pagination_limit_param_help' => 'Názov parametra dopytu, ktorý nesie veľkosť stránky, napr. <code>limit</code>, <code>per_page</code> alebo <code>page_size</code>.',
    'custom_pagination_offset_param_help' => 'Názov parametra dopytu, ktorý nesie počiatočný posun, napr. <code>offset</code>, <code>start</code> alebo <code>skip</code>.',
    'custom_pagination_page_param_help' => 'Názov parametra dopytu, ktorý nesie číslo stránky, napr. <code>page</code> alebo <code>p</code>.',
    'custom_pagination_page_start_help' => 'Číslo prvej stránky. Predvolene <code>1</code>. Pre API, ktoré číslujú stránky od nuly, nastavte <code>0</code>.',
    'custom_pagination_next_path_help' => 'Cesta s bodkami v tele odpovede, ktorá ukazuje na absolútnu URL adresu ďalšej stránky, napr. <code>links.next</code> alebo <code>meta.next_page_url</code>. Keď je cesta prázdna alebo chýba, stránkovanie sa zastaví.',
    'custom_field_paths_label' => 'Cesty v odpovedi poskytovateľa',
    'custom_field_paths_help' => 'Každý cieľ v Snipe-IT (štandardné pole, vlastné pole alebo natívny stĺpec) namapujte na cestu s bodkami, kde sa jeho hodnota nachádza v jednom zázname odpovede JSON od poskytovateľa. Vyberte cieľ, zadajte cestu s bodkami (napr. <code>hardware.serial</code>), zvoľte smer (stiahnuť / odoslať / oboje) a potom kliknite na Pridať.',
    'field_map_column_field' => 'Pole Snipe-IT',
    'field_map_column_path' => 'Cesta s bodkami u poskytovateľa',
    'field_map_column_direction' => 'Smer',
    'field_map_empty' => 'Zatiaľ nie sú namapované žiadne polia.',
    'field_map_pick_field' => 'Vyberte pole',
    'field_map_new_path' => 'Cesta s bodkami (napr. hardware.serial)',
    'custom_push_method_help' => 'Metóda HTTP, ktorú adaptér používa pri odosielaní aktualizácií späť do vášho API. Predvolene <code>PATCH</code>.',
    'custom_push_path_help' => 'Cesta pripojená k základnej URL adrese pri odosielaní. Podporuje zástupný symbol <code>{external_id}</code>, ktorý sa nahradí ID zariadenia na strane poskytovateľa zaznamenaným pri poslednom stiahnutí každého majetku. Ak chcete volať priamo základnú URL adresu, nechajte prázdne (užitočné, ak vaše API prijíma ID v tele požiadavky namiesto URL). Ak chcete odosielanie úplne vypnúť, nastavte metódu HTTP pre odosielanie na <code>Disabled</code>.',
    'custom_push_notes_target_help' => 'Voliteľné. Cesta s bodkami v odosielaných údajoch, kam sa má synchronizovať hodnota zo šablóny zložených poznámok na odoslanie, napr. <code>metadata.notes</code>. Ak zložené poznámky nepoužívate, nechajte prázdne.',

